  ],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": [
    "C34", "C35", "C04", "C13", "C19", "C22",
    "C46", "C56", "C58", "C67", "C72", "C77"
  ],
  "claims": [
    {
      "claim": "The query is moclobemide; L3 human records show rapid oral absorption with Tmax about 1.44 h in normal subjects and 1.46 h in renally impaired subjects after single oral dosing, supporting absorption but not quantifying extent.",
      "card_ids": ["C34", "C35"]
    },
    {
      "claim": "Close structural analog procainamide and its NAPA metabolite have measured absolute oral bioavailability values of 68–92%, with L2 context of 75–85% and acecainide 85%, all well above the 20% threshold.",
      "card_ids": ["C04", "C13", "C19", "C22", "C24", "C31"]
    },
    {
      "claim": "L4 records show high fraction absorbed for related or similarly small oral drugs (NAPA 87–92%, levocetirizine ≥85%, bepotastine >85%, isoniazid Fa 0.97–0.99, rivaroxaban 80–100%), supporting favorable intestinal absorption.",
      "card_ids": ["C46", "C56", "C45", "C49", "C51", "C53", "C47", "C48", "C52"]
    },
    {
      "claim": "L5 bidirectional permeability records show high permeability and low efflux for diverse compounds, including morpholine-amide-containing molecules, with no supplied record indicating significant gut-wall efflux or intestinal metabolism for the query or close analogs.",
      "card_ids": ["C58", "C59", "C67", "C57", "C63", "C66"]
    },
    {
      "claim": "L6 hepatic clearance records are mixed and not moclobemide-specific: some morpholine-amide-containing compounds show low intrinsic clearance or good stability (C72, C77, C75, C73, C71), while others show moderate-to-high CLint (C70, C74, C78, C80); no direct moclobemide hepatic clearance measurement is supplied, so this does not provide affirmative evidence for F < 20%.",
      "card_ids": ["C72", "C77", "C75", "C73", "C71", "C70", "C74", "C78", "C80"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C69", "C70", "C71", "C72", "C73", "C74", "C75", "C76", "C77", "C78", "C79", "C80"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for moclobemide itself was supplied; the decision relies on structural analogy to procainamide/NAPA, the physicochemical prior, and indirect exposure/absorption/permeability records.",
    "No fed-state-specific moclobemide bioavailability or absorption record is available; the fed condition is not shown to reduce F below 20%.",
    "L6 hepatic clearance records are for other molecules and are mixed; no direct moclobemide hepatic clearance or first-pass quantification is available.",
    "No direct intestinal metabolism or gut-wall efflux measurement for moclobemide was supplied.",
    "L3 direct moclobemide records provide only Tmax, not AUC/Cmax or F."
  ],
  "decision_summary": "The query is moclobemide. L6 adds mixed hepatic clearance/metabolic-stability records for other molecules, with no direct moclobemide measurement; low-clearance records for some morpholine-amide-containing compounds are mechanistically supportive, while high-CLint records for other scaffolds are not transferable enough to overturn the prediction. Combined with L3 rapid absorption (Tmax ~1.4 h), L4 high fraction absorbed for related/small oral drugs, L5 high permeability/low efflux, and procainamide/NAPA absolute F 68–92%, the evidence supports F ≥ 20%. Confidence remains moderate because no direct moclobemide F or fed-state-specific measurement was supplied."
}

